  const next = () => { seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0; return seed; };
  for (let n = 0; n < 200; n++) {
    const a = Object.freeze(Array.from({ length: next() % 50 }, () => ['', '-', '+', ' ', 'x'][next() % 5]));
