'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const { performance } = require('node:perf_hooks');
const { diffLines, unifiedHunks, applyHunks } = require('./src/diff');

function distance(a, b) {
  let previous = new Array(b.length + 1).fill(0);
  for (const line of a) {
    const row = [0];
    for (let j = 0; j < b.length; j++) {
      row.push(line === b[j] ? previous[j] + 1 : Math.max(previous[j + 1], row[j]));
    }
    previous = row;
  }
  return a.length + b.length - 2 * previous[b.length];
}

function check(a, b) {
  const script = diffLines(a, b);
  assert.deepEqual(script.filter(e => e.op !== 'insert').map(e => e.line), a);
  assert.deepEqual(script.filter(e => e.op !== 'delete').map(e => e.line), b);
  assert.equal(script.filter(e => e.op !== 'equal').length, distance(a, b));
  assert.deepEqual(diffLines(a, b), script);
  let inserted = false;
  for (const entry of script) {
    if (entry.op === 'equal') inserted = false;
    if (entry.op === 'insert') inserted = true;
    if (entry.op === 'delete') assert.equal(inserted, false);
  }
  for (const context of [0, 1, 2, 5]) {
    const hunks = unifiedHunks(a, b, { context });
    for (const hunk of hunks) {
      Object.freeze(hunk.lines);
      Object.freeze(hunk);
    }
    Object.freeze(hunks);
    assert.deepEqual(applyHunks(a, hunks), b);
    if (a.length === b.length && a.every((line, i) => line === b[i])) {
      assert.deepEqual(hunks, []);
    }
  }
}

test('exhaustive minimal scripts and frozen patch roundtrips', () => {
  const arrays = [Object.freeze([])];
  let level = arrays.slice();
  for (let n = 1; n <= 4; n++) {
    level = level.flatMap(a => ['', 'repeat', '+prefix'].map(line => Object.freeze([...a, line])));
    arrays.push(...level);
  }
  for (const a of arrays) for (const b of arrays) check(a, b);
});

test('longer deterministic repetitive inputs', () => {
  let seed = 1729;
  const next = () => { seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0; return seed; };
  for (let n = 0; n < 200; n++) {
    const a = Object.freeze(Array.from({ length: next() % 50 }, () => ['', '-', '+', ' ', 'x'][next() % 5]));
    const b = Object.freeze(Array.from({ length: next() % 50 }, () => ['', '-', '+', ' ', 'x'][next() % 5]));
    check(a, b);
  }
});

test('exact coordinates, context boundaries and untouched gaps', () => {
  assert.deepEqual(unifiedHunks(['a', 'b'], ['x', 'a', 'b'], { context: 0 }), [
    { oldStart: 0, oldLines: 0, newStart: 1, newLines: 1, lines: ['+x'] },
  ]);
  assert.deepEqual(unifiedHunks(['a', 'b'], ['a', 'b', 'x'], { context: 0 }), [
    { oldStart: 2, oldLines: 0, newStart: 3, newLines: 1, lines: ['+x'] },
  ]);
  assert.deepEqual(unifiedHunks(['x', 'a', 'b'], ['a', 'b'], { context: 0 }), [
    { oldStart: 1, oldLines: 1, newStart: 0, newLines: 0, lines: ['-x'] },
  ]);
  assert.deepEqual(unifiedHunks(['a', 'b', 'x'], ['a', 'b'], { context: 0 }), [
    { oldStart: 3, oldLines: 1, newStart: 2, newLines: 0, lines: ['-x'] },
  ]);
  assert.deepEqual(unifiedHunks(['a', 'b', 'c', 'd'], ['A', 'b', 'c', 'D'], { context: 1 }), [
    { oldStart: 1, oldLines: 4, newStart: 1, newLines: 4, lines: ['-a', '+A', ' b', ' c', '-d', '+D'] },
  ]);
  assert.deepEqual(unifiedHunks(['a', 'b', 'c', 'd', 'e'], ['A', 'b', 'c', 'd', 'E'], { context: 1 }), [
    { oldStart: 1, oldLines: 2, newStart: 1, newLines: 2, lines: ['-a', '+A', ' b'] },
    { oldStart: 4, oldLines: 2, newStart: 4, newLines: 2, lines: [' d', '-e', '+E'] },
  ]);
  const a = Object.freeze(['a', 'b', 'c', 'd', 'e']);
  const hunks = [
    { oldStart: 0, oldLines: 0, newStart: 1, newLines: 2, lines: ['+x', '+y'] },
    { oldStart: 3, oldLines: 1, newStart: 4, newLines: 0, lines: ['-c'] },
    { oldStart: 5, oldLines: 0, newStart: 7, newLines: 1, lines: ['+z'] },
  ];
  assert.deepEqual(applyHunks(a, hunks), ['x', 'y', 'a', 'b', 'd', 'e', 'z']);
  const copy = applyHunks(a, []);
  assert.deepEqual(copy, a);
  assert.notEqual(copy, a);
  check(Object.freeze(['', '+x', '-y', ' z']), Object.freeze(['+x', '', '-z', ' z']));
});

test('malformed, mismatching, overlapping and misordered hunks fail at their index', () => {
  const a = ['a', 'b', 'c'];
  const valid = { oldStart: 1, oldLines: 1, newStart: 1, newLines: 1, lines: ['-a', '+A'] };
  const invalid = [null, {}, { ...valid, lines: null }, { ...valid, lines: ['?a'] },
    { ...valid, lines: [''] }, { ...valid, lines: [1] }, { ...valid, lines: ['-wrong', '+A'] },
    { ...valid, lines: [' wrong'] }, { ...valid, oldLines: 2 }, { ...valid, newLines: 2 },
    { ...valid, oldStart: 0 }, { ...valid, newStart: 0 }, { ...valid, oldStart: 4 },
    { ...valid, oldStart: -1 }, { ...valid, oldLines: 0.5 }, { ...valid, newLines: NaN },
    { ...valid, newStart: Infinity }, { ...valid, oldStart: '1' },
    { ...valid, lines: ['-a', '-b', '+A'] }, { ...valid, lines: ['-a', '+A', '+B'] }];
  for (const hunk of invalid) assert.throws(() => applyHunks(a, [hunk]), /hunk 0 does not apply/);
  assert.throws(() => applyHunks(a, [valid, valid]), /hunk 1 does not apply/);
  assert.throws(() => applyHunks(a, [
    { oldStart: 3, oldLines: 1, newStart: 3, newLines: 1, lines: ['-c', '+C'] }, valid,
  ]), /hunk 1 does not apply/);
  assert.throws(() => applyHunks(a, [
    { oldStart: 0, oldLines: 0, newStart: 1, newLines: 1, lines: ['+x'] },
    { oldStart: 3, oldLines: 1, newStart: 3, newLines: 1, lines: ['-c', '+C'] },
  ]), /hunk 1 does not apply/);
  for (const context of [-1, 0.5, Infinity, NaN]) {
    assert.throws(() => unifiedHunks(a, a, { context }), RangeError);
  }
});

test('20,000-line small changes run below one second', () => {
  for (const repetitive of [false, true]) {
    const a = Array.from({ length: 20000 }, (_, i) => repetitive ? `repeat ${i % 3}` : `line ${i}`);
    const b = a.slice();
    b.splice(10, 1, 'replacement');
    b.splice(10000, 0, 'inserted');
    b.splice(19000, 1);
    const start = performance.now();
    const script = diffLines(a, b);
    const hunks = unifiedHunks(a, b);
    const result = applyHunks(a, hunks);
    const elapsed = performance.now() - start;
    assert.deepEqual(result, b);
    assert.equal(script.filter(e => e.op !== 'equal').length, 4);
    assert.ok(elapsed < 1000, `elapsed ${elapsed}ms`);
    console.log(`20,000 lines (${repetitive ? 'repetitive' : 'unique'}): ${elapsed.toFixed(2)}ms for diff + hunks + apply`);
  }
});

